const stateDefault={completed:{},runLogs:[],gymLogs:{},food:[],sleep:[],iceBathLogs:{},recoveryCheckins:{},recoveryPrefs:{set:false,lowC:10,highC:15,minutes:5,weekly:0},healthRuns:[],healthSleep:[],healthSyncedAt:null,selectedDate:null,selectedView:'today',prefs:{bedtime:'22:30',wake:'06:30',diet:'kosher-friendly',goal:'Finish strong; 3:30 stretch goal'}};
