const s={...stateDefault,...saved,iceBathLogs:{...stateDefault.iceBathLogs,...(saved.iceBathLogs||{})},recoveryCheckins:{...stateDefault.recoveryCheckins,...(saved.recoveryCheckins||{})},recoveryPrefs:{...stateDefault.recoveryPrefs,...(saved.recoveryPrefs||{})},prefs:{...stateDefault.prefs,...(saved.prefs||{})}};
