 const override=trainingOverrides[d]; if(override){const type=override.activity==='Marathon race'?'race':override.activity==='Long easy run'?'long':'run';const match=String(override.instructions||'').match(/STRETCH_KM:(\d+)/);return {type,label:override.activity,miles:Number(override.planned_km)/1.609344,icon:type==='race'?'🏁':type==='long'?'🏃':'🏃',kind:type==='race'||type==='long'?'long':'run',instructions:override.instructions||'',optional:override.activity==='Optional easy run',stretchKm:match?Number(match[1]):0};}
 if(wd===2 && OPTIONAL_TUESDAYS[d])return{type:'run',label:'Optional easy run',miles:kmToMiles(OPTIONAL_TUESDAYS[d]),icon:'🏃',kind:'run',optional:true};
